{
  "name": "wavesurfer.js",
  "version": "8.1.0",
  "license": "BSD-3-Clause",
  "author": "katspaugh",
  "description": "Audio waveform player",
  "homepage": "https://wavesurfer.xyz",
  "keywords": [
    "waveform",
    "spectrogram",
    "audio",
    "player",
    "music",
    "linguistics"
  ],
  "repository": {
    "type": "git",
    "url": "git@github.com:katspaugh/wavesurfer.js.git"
  },
  "type": "module",
  "files": [
    "dist"
  ],
  "main": "./dist/wavesurfer.js",
  "unpkg": "./dist/wavesurfer.min.js",
  "module": "./dist/wavesurfer.js",
  "browser": "./dist/wavesurfer.js",
  "types": "./dist/wavesurfer.d.ts",
  "exports": {
    ".": {
      "types": "./dist/wavesurfer.d.ts",
      "import": "./dist/wavesurfer.esm.js",
      "require": "./dist/wavesurfer.cjs"
    },
    "./dist/plugins/*.js": {
      "types": "./dist/plugins/*.d.ts",
      "import": "./dist/plugins/*.esm.js",
      "require": "./dist/plugins/*.cjs"
    },
    "./plugins/*": {
      "types": "./dist/plugins/*.d.ts",
      "import": "./dist/plugins/*.esm.js",
      "require": "./dist/plugins/*.cjs"
    },
    "./dist/plugins/*.esm.js": {
      "types": "./dist/plugins/*.d.ts",
      "import": "./dist/plugins/*.esm.js",
      "require": "./dist/plugins/*.cjs"
    },
    "./dist/*.js": {
      "types": "./dist/*.d.ts",
      "import": "./dist/*.js"
    }
  },
  "scripts": {
    "clean": "node ./scripts/clean.cjs",
    "build:dev": "tsc -w --target ESNext",
    "build": "npm run clean && tsc && rollup -c && node ./scripts/verify-exports.cjs",
    "lint": "eslint \"src/**/*.ts\" --max-warnings 0",
    "lint:fix": "eslint \"src/**/*.ts\" --fix",
    "lint:report": "eslint \"src/**/*.ts\" --output-file eslint_report.json --format json",
    "typecheck": "tsc --noEmit && tsc -p tsconfig.test.json --noEmit",
    "prettier": "prettier -w '**/*.{js,ts,css}' --ignore-path .gitignore",
    "make-plugin": "./scripts/plugin.sh",
    "verify-exports": "node ./scripts/verify-exports.cjs",
    "cypress": "cypress open --e2e",
    "cypress:canary": "cypress open --e2e -b chrome:canary",
    "test": "cypress run --browser ${CYPRESS_BROWSER:-chromium}",
    "test:unit": "jest --coverage --selectProjects default",
    "test:leaks": "NODE_OPTIONS=--expose-gc jest --selectProjects leaks --runInBand --coverage=false",
    "serve": "npx live-server --port=9090 --no-browser --ignore='.*,src,cypress,scripts'",
    "start": "npm run build:dev & npm run serve",
    "dev": "npm run start",
    "prepare": "npm run build"
  },
  "packageManager": "yarn@1.22.22",
  "devDependencies": {
    "@rollup/plugin-terser": "^0.4.4",
    "@rollup/plugin-typescript": "^12.3.0",
    "@types/jest": "^29.5.2",
    "@typescript-eslint/eslint-plugin": "^8.60.1",
    "@typescript-eslint/parser": "^8.60.1",
    "cypress": "^13.17.0",
    "cypress-image-snapshot": "^4.0.1",
    "eslint": "^9.39.4",
    "eslint-config-prettier": "^9.1.0",
    "eslint-plugin-prettier": "^5.5.6",
    "glob": "^11.1.0",
    "jest": "^29.7.0",
    "jest-environment-jsdom": "^29.7.0",
    "prettier": "^3.8.3",
    "rollup": "^4.61.1",
    "rollup-plugin-web-worker-loader": "^1.7.0",
    "ts-jest": "^29.4.11",
    "typescript": "^5.9.3"
  }
}

