export const ERB_A = (1000 * Math.log(10)) / (24.7 * 4.37)

// Frequency scaling functions
export function hzToMel(hz: number): number {
  return 2595 * Math.log10(1 + hz / 700)
}

export function melToHz(mel: number): number {
  return 700 * (Math.pow(10, mel / 2595) - 1)
}

export function hzToLog(hz: number): number {
  return Math.log10(Math.max(1, hz))
}

export function logToHz(log: number): number {
  return Math.pow(10, log)
}

/**
 * The raw Traunmüller-corrected bark value at 0 Hz (~-0.1505): raw bark(0) = -0.53, then the
 * bark < 2 correction adds 0.15 * (2 + 0.53). Subtracted in hzToBark (and added back in
 * barkToHz, keeping the pair exact inverses) so hzToBark(0) === 0 - the vertical-mapping code
 * (renderChannelToCanvas / drawSpectrogramSegment) divides hzToScale values assuming every
 * scale maps 0 Hz to 0, and the raw bark offset produced a slightly negative rMin and
 * out-of-range bitmap source rows (~0.6% offset). Written with the exact operations hzToBark
 * itself performs at 0 Hz so the subtraction cancels to exactly 0 in floating point.
 */
const BARK_ZERO_OFFSET = 0.15 * (2 + 0.53) - 0.53

export function hzToBark(hz: number): number {
  // https://www.mathworks.com/help/audio/ref/hz2bark.html#function_hz2bark_sep_mw_06bea6f7-353b-4479-a58d-ccadb90e44de
  let bark = (26.81 * hz) / (1960 + hz) - 0.53
  if (bark < 2) {
    bark += 0.15 * (2 - bark)
  }
  if (bark > 20.1) {
    bark += 0.22 * (bark - 20.1)
  }
  // Normalize so 0 Hz maps to exactly 0 (see BARK_ZERO_OFFSET above)
  return bark - BARK_ZERO_OFFSET
}

export function barkToHz(bark: number): number {
  // https://www.mathworks.com/help/audio/ref/bark2hz.html#function_bark2hz_sep_mw_bee310ea-48ac-4d95-ae3d-80f3e4149555
  // Undo hzToBark's zero-normalization shift first, so the pair stays exact inverses
  bark += BARK_ZERO_OFFSET
  if (bark < 2) {
    bark = (bark - 0.3) / 0.85
  }
  if (bark > 20.1) {
    bark = (bark + 4.422) / 1.22
  }
  return 1960 * ((bark + 0.53) / (26.28 - bark))
}

export function hzToErb(hz: number): number {
  // https://www.mathworks.com/help/audio/ref/hz2erb.html#function_hz2erb_sep_mw_06bea6f7-353b-4479-a58d-ccadb90e44de
  return ERB_A * Math.log10(1 + hz * 0.00437)
}

export function erbToHz(erb: number): number {
  // https://it.mathworks.com/help/audio/ref/erb2hz.html?#function_erb2hz_sep_mw_bee310ea-48ac-4d95-ae3d-80f3e4149555
  return (Math.pow(10, erb / ERB_A) - 1) / 0.00437
}

// Generic scale conversion functions
export function hzToScale(hz: number, scale: 'linear' | 'logarithmic' | 'mel' | 'bark' | 'erb'): number {
  switch (scale) {
    case 'mel':
      return hzToMel(hz)
    case 'logarithmic':
      return hzToLog(hz)
    case 'bark':
      return hzToBark(hz)
    case 'erb':
      return hzToErb(hz)
    default:
      return hz
  }
}

export function scaleToHz(scale: number, scaleType: 'linear' | 'logarithmic' | 'mel' | 'bark' | 'erb'): number {
  switch (scaleType) {
    case 'mel':
      return melToHz(scale)
    case 'logarithmic':
      return logToHz(scale)
    case 'bark':
      return barkToHz(scale)
    case 'erb':
      return erbToHz(scale)
    default:
      return scale
  }
}

/**
 * One output row of a sparse frequency-scale filter bank. Every row produced by the (dense)
 * filter-bank construction has exactly two adjacent non-zero taps, so storing just those (plus the
 * row's center frequency) lets the bank be applied in O(filters) instead of O(filters × bins).
 */
export interface SparseFilter {
  /** Index of the lower of the two adjacent FFT bins (the upper tap is lo + 1) */
  lo: number
  /** Weight of the lower bin */
  weightLo: number
  /** Weight of the upper bin */
  weightHi: number
  /** Center frequency of this output row in Hz */
  centerHz: number
}

function createSparseFilterBank(
  numFilters: number,
  fftSamples: number,
  sampleRate: number,
  hzToScaleFunc: (hz: number) => number,
  scaleToHzFunc: (scale: number) => number,
): SparseFilter[] {
  const filterMin = hzToScaleFunc(0)
  const filterMax = hzToScaleFunc(sampleRate / 2)
  const filterBank: SparseFilter[] = new Array(numFilters)
  const scale = sampleRate / fftSamples

  for (let i = 0; i < numFilters; i++) {
    const hz = scaleToHzFunc(filterMin + (i / numFilters) * (filterMax - filterMin))
    const j = Math.floor(hz / scale)
    const hzLow = j * scale
    const hzHigh = (j + 1) * scale
    const r = (hz - hzLow) / (hzHigh - hzLow)
    filterBank[i] = { lo: j, weightLo: 1 - r, weightHi: r, centerHz: hz }
  }
  return filterBank
}

export function applySparseFilterBank(fftPoints: Float32Array, filterBank: SparseFilter[]): Float32Array {
  const numFilters = filterBank.length
  const logSpectrum = new Float32Array(numFilters)
  for (let i = 0; i < numFilters; i++) {
    const { lo, weightLo, weightHi } = filterBank[i]
    if (lo >= 0 && lo < fftPoints.length) {
      logSpectrum[i] = fftPoints[lo] * weightLo
    }
    if (lo + 1 >= 0 && lo + 1 < fftPoints.length) {
      logSpectrum[i] += fftPoints[lo + 1] * weightHi
    }
  }
  return logSpectrum
}

// Sparse filter-bank construction, keyed by scale type
export function createSparseFilterBankForScale(
  scale: 'linear' | 'logarithmic' | 'mel' | 'bark' | 'erb',
  numFilters: number,
  fftSamples: number,
  sampleRate: number,
): SparseFilter[] | null {
  switch (scale) {
    case 'mel':
      return createSparseFilterBank(numFilters, fftSamples, sampleRate, hzToMel, melToHz)
    case 'logarithmic':
      return createSparseFilterBank(numFilters, fftSamples, sampleRate, hzToLog, logToHz)
    case 'bark':
      return createSparseFilterBank(numFilters, fftSamples, sampleRate, hzToBark, barkToHz)
    case 'erb':
      return createSparseFilterBank(numFilters, fftSamples, sampleRate, hzToErb, erbToHz)
    case 'linear':
    default:
      return null // No filter bank for linear scale
  }
}

/**
 * Global-peak level, measured before pre-emphasis, below which autoGain treats the whole signal as
 * digital silence and leaves the spectrogram blank instead of amplifying the numeric floor.
 * -180 dBFS is well below the quantization floor of 24-bit audio (~-144 dBFS) and float32 near
 * full scale (~-138 dB), but far above denormals, so it only triggers on true silence.
 */
export const SILENCE_FLOOR_DB = -180

/**
 * autoGain transient-memory budget: below this estimate (frames x bins x 4 bytes x channels)
 * the Float32 dB frames are kept between the two passes (single FFT pass, fastest); at or
 * above it, only the running maximum is kept and the spectra are recomputed for quantization,
 * trading a second FFT pass on very long short-window files for a bounded heap.
 */
export const AUTO_GAIN_BUFFER_BUDGET_BYTES = 64 * 1024 * 1024

/**
 * Per-bin display tilt in dB: preEmphasis dB/octave relative to 1 kHz - 0 dB at 1 kHz,
 * boosting above, attenuating below. This is Praat's display pre-emphasis formula, including
 * its 1e-308 guard that sends the DC bin toward -infinity instead of NaN. Unlike Praat, the 0 Hz
 * row is attenuated for negative pre-emphasis too, so the guard can't make it the loudest bin.
 */
export function createPreEmphasisTilt(preEmphasis: number, binFrequencies: ArrayLike<number>): Float64Array {
  if (!Number.isFinite(preEmphasis)) {
    throw new TypeError(`preEmphasis must be a finite number, got ${preEmphasis}`)
  }
  const tilt = new Float64Array(binFrequencies.length)
  for (let i = 0; i < binFrequencies.length; i++) {
    const term = preEmphasis * Math.log2(binFrequencies[i] / 1000 + 1e-308)
    tilt[i] = binFrequencies[i] > 0 ? term : -Math.abs(term)
  }
  return tilt
}

/** Center frequency in Hz of each output row: sparse scale rows, or linear FFT bins */
export function getBinFrequencies(
  filterBank: SparseFilter[] | null,
  fftLength: number,
  sampleRate: number,
): Float64Array {
  if (filterBank) {
