    fontType: string,
    textColorFreq: string | undefined,
    textColorUnit: string | undefined,
    textAlign: CanvasTextAlign,
    channels: number,
  ): void {
    if (!labelsEl) return

    drawFrequencyLabels(labelsEl, {
      bgFill,
      fontSizeFreq,
      fontSizeUnit,
      fontType,
      textColorFreq,
      textColorUnit,
      textAlign,
      channels,
      height: settings.height,
      frequencyMin: settings.frequencyMin,
      frequencyMax,
      scale: settings.scale,
    })
  }

  function fillImageDataQuality(
    data: Uint8ClampedArray,
    segmentPixels: Uint8Array[],
    segmentWidth: number,
    bitmapHeight: number,
  ): void {
    // High quality rendering - process all pixels
    for (let i = 0; i < segmentWidth; i++) {
      paintColumnPixels(data, segmentPixels[i], colorMap, i, segmentWidth, bitmapHeight)
    }
  }

  // ---- Wire up to wavesurfer (replaces the pre-port onInit()) ----
  let container: HTMLElement | null = null
  if (options.container) {
    if (typeof options.container === 'string') {
      const el = document.querySelector(options.container)
      if (el instanceof HTMLElement) {
        container = el
      } else {
        // Falls back to the wavesurfer wrapper below rather than throwing - warn so a typo'd
        // selector doesn't silently render the spectrogram somewhere the caller didn't expect.
        console.warn(
          `SpectrogramPlugin: no element found for container selector "${options.container}", falling back to the wavesurfer wrapper`,
        )
      }
    } else if (isHTMLElement(options.container)) {
      container = options.container
    }
  }
  if (!container) {
    container = ctx.wavesurfer.getWrapper()
  }
  container.appendChild(wrapper)
  ctx.scope.add(() => wrapper.remove())
  ctx.scope.add(() => canvasContainer.remove())
  ctx.scope.add(() => labelsEl?.remove())

  if (ctx.wavesurfer.options.fillParent) {
    Object.assign(wrapper.style, {
      width: '100%',
      overflowX: 'hidden',
      overflowY: 'hidden',
    })
  }

  if (isWindowed) {
    // Windowed rendering reacts to playback position, scroll, and zoom directly (there's no
    // single full-buffer render to throttle) - the same event set the pre-unification
    // WindowedSpectrogramPlugin's onInit() subscribed.
    ctx.scope.add(ctx.wavesurfer.on('timeupdate', () => scheduleWindowedRender()))
    ctx.scope.add(ctx.wavesurfer.on('scroll', () => scheduleWindowedRender()))
    ctx.scope.add(ctx.wavesurfer.on('redraw', () => handleWindowedRedraw()))
    ctx.scope.add(
      ctx.wavesurfer.on('ready', () => {
        const decodedData = ctx.wavesurfer?.getDecodedData()
        if (decodedData) startWindowedRender(decodedData)
      }),
    )

    // Trigger initial render after init, same as full mode below, in case 'ready' already
    // fired before this plugin was registered.
    if (ctx.wavesurfer.getDecodedData()) {
      ctx.scope.timeout(() => {
        const decodedData = ctx.wavesurfer?.getDecodedData()
        if (decodedData) startWindowedRender(decodedData)
      }, 0)
    }
  } else {
    ctx.scope.add(ctx.wavesurfer.on('redraw', () => throttledRender()))

    // Trigger initial render after init. This ensures the spectrogram appears even if no
    // redraw event is fired.
    if (ctx.wavesurfer.getDecodedData()) {
      ctx.scope.timeout(() => throttledRender(), 0)
    }
  }

  // Initialize worker if enabled
  if (useWebWorker) {
    workerClient.initialize()
  }

  // ---- Teardown (replaces the pre-port destroy() override) ----
  ctx.scope.add(() => {
    // Clean up worker, rejecting any in-flight requests
    workerClient.dispose(new Error('Spectrogram plugin destroyed'))

    // Reject pending setOptions() calls and stop their redraw
    cancelSettingsRedraw?.()
    cancelSettingsRedraw = null
    settleRequests(Infinity, abortError('The spectrogram plugin was destroyed'))

    // Release the decoded buffer and caches
    cachedFrequencies = null
    cachedResampledData = null
    cachedBuffer = null
    buffer = null

    // Clean up scroll listener
    scrollUnsubscribe?.()
    scrollUnsubscribe = null

    clearCanvases()

    // Windowed rendering: stop any pending progressive-load timer and drop every segment's
    // canvas from the DOM (clearCanvases() above only knows about full mode's own `canvases`
    // array, not the segment manager's per-segment canvases).
    segmentManager?.dispose()
    segmentManager?.clearAllSegments()
  })

  const testInternals: TestInternals = {
    get buffer() {
      return buffer
    },
    set buffer(value: AudioBuffer | null) {
      buffer = value
    },
    get worker() {
      return workerClient.worker
    },
    get workerPromises() {
      return workerClient.pending
    },
    get cachedFrequencies() {
      return cachedFrequencies
    },
    get cachedResampledData() {
      return cachedResampledData
    },
    get cachedBuffer() {
      return cachedBuffer
    },
    get canvasContainer() {
      return canvasContainer
    },
    get canvases() {
      return canvases
    },
    get drawnCanvases() {
      return drawnCanvases
    },
    get maxCanvasWidth() {
      return maxCanvasWidth
    },
    get autoGainBudgetBytes() {
      return autoGainBudgetBytes
    },
    set autoGainBudgetBytes(value: number) {
      autoGainBudgetBytes = value
    },
    getFrequencies,
    calculateFrequenciesWithWorker,
    drawSpectrogram,
    windowed: isWindowed
      ? {
          segmentManager: segmentManager as SegmentManager,
          calculateFrequencies: calculateFrequenciesForRange,
          calculateFrequenciesMainThread: calculateFrequenciesMainThreadRange,
          calculateFrequenciesWithWorker: calculateFrequenciesWithWorkerRange,
        }
      : undefined,
  }

  return {
    loadFrequenciesData,
    getFrequenciesData,
    clearCache,
    getOptions: () => ({ ...currentOptions }),
    setOptions,
    getLoadingProgress: () => segmentManager?.getLoadingProgress() ?? 100,
    stopProgressiveLoading: () => segmentManager?.stopProgressiveLoading(),
    restartProgressiveLoading: () => segmentManager?.restartProgressiveLoading(),
    __spectrogramInternalsForTests: () => testInternals,
  }
}

// Spectrogram plugin example

import WaveSurfer from 'wavesurfer.js'
import Spectrogram from 'wavesurfer.js/dist/plugins/spectrogram.esm.js'

// Create an instance of WaveSurfer
const ws = WaveSurfer.create({
  container: '#waveform',
  waveColor: 'rgb(200, 0, 200)',
  progressColor: 'rgb(100, 0, 100)',
  url: '/examples/audio/audio.wav',
  sampleRate: 44100,
})

// Initialize the Spectrogram plugin with detailed configuration.
// registerPlugin() returns the plugin instance, which is what emits
// the spectrogram's own 'ready' and 'click' events.
const spectrogram = ws.registerPlugin(
  Spectrogram.create({
    // Display frequency labels on the left side
    labels: true,

    // Height of the spectrogram in pixels
    height: 200,

    // Render separate spectrograms for each audio channel
    // Set to false to combine all channels into one spectrogram
    splitChannels: true,

    // Frequency scale type:
    // - 'linear': Standard linear frequency scale (0-20kHz)
    // - 'logarithmic': Logarithmic scale, better for low frequencies
    // - 'mel': Mel scale based on human hearing perception (default)
    // - 'bark': Bark scale for psychoacoustic analysis
    // - 'erb': ERB scale for auditory filter modeling
    scale: 'mel',

    // Frequency range to display (in Hz)
    frequencyMax: 8000, // Maximum frequency to show
    frequencyMin: 0, // Minimum frequency to show

    // FFT parameters
    fftSamples: 1024, // Number of samples for FFT (must be power of 2)
    // Higher values = better frequency resolution, slower rendering

    // Visual styling
    labelsBackground: 'rgba(0, 0, 0, 0.1)', // Background for frequency labels

    // Performance optimization
    useWebWorker: true, // Use web worker for FFT calculations (improves performance)
    // fallbackToMainThread: true, // Set false to emit 'error' instead of computing a failed
    //                                worker FFT on the main thread (can freeze on long files)

    // For very long audio files, render only the visible time range instead of
    // the whole file up front (replaces the deprecated WindowedSpectrogramPlugin -
    // see examples/spectrogram-windowed.js):
    // rendering: 'windowed',
    // progressiveLoading: true, // windowed only: keep loading segments in the background

    // Additional options you can configure:
    //
    // Window function for FFT (affects frequency resolution vs time resolution):
    // windowFunc: 'hann' | 'hamming' | 'blackman' | 'bartlett' | 'cosine' | 'gauss' | 'lanczoz' | 'rectangular' | 'triangular'
    //
    // Color mapping for frequency intensity:
    // colorMap: 'gray' | 'igray' | 'roseus' | custom array
    //
    // Gain and range for color scaling:
    // gainDB: 20,        // Brightness adjustment (default: 20dB)
    // rangeDB: 80,       // Dynamic range (default: 80dB)
    //
    // Praat-style display options (combine with windowFunc: 'gauss', scale: 'linear',
    // colorMap: 'gray' and rangeDB: 70 for the classic Praat look):
    // preEmphasis: 6,    // dB/octave boost above 1 kHz so speech formants stay visible
    // autoGain: true,    // Map the loudest bin to black instead of using the fixed gainDB
    // dynamicCompression: 0.4, // 0-1: lift quieter frames toward the loudest level
    //
    // Overlap between FFT windows:
    // noverlap: null,    // null = auto (default), 0 = no overlap
    //
    // Zero-padded FFT length (power of 2, >= fftSamples):
    // fftSize: 4096,     // Interpolates extra frequency bins for a smoother image without
    //                    // changing the analysis window, hop, or time resolution
    //
    // Maximum canvas width for performance:
    // maxCanvasWidth: 30000,  // Split large spectrograms into multiple canvases
  }),
)

// Play audio when user clicks on the waveform
ws.once('interaction', () => {
  ws.play()
})

// Event listeners for spectrogram interactions.
// These are emitted by the plugin instance, not by wavesurfer.
spectrogram.on('ready', () => {
  console.log('Spectrogram has finished rendering')
})

spectrogram.on('click', (relativeX) => {
  console.log('Clicked on spectrogram at position:', relativeX)
  // You can use relativeX to seek to that position in the audio
  ws.setTime(relativeX * ws.getDuration())
})

