  {
    const { percentages, bounds } = this.renderer.getScrollSignals()
    // A scroll updates both signals, so this effect runs once per signal.
    // Both already hold the new metrics by then (the scroll stream batches
    // its writes), so the second run would emit the very same event again:
    // skip a run that repeats the last emission.
    let emitted = false
    let lastStartX = 0
    let lastEndX = 0
    let lastLeft = 0
    let lastRight = 0
    let lastDuration = 0
    this.scope.add(
      effect(() => {
        const { startX, endX } = percentages.value
        const { left: scrollLeft, right: scrollRight } = bounds.value
        const duration = this.getDuration()
        if (
          emitted &&
          startX === lastStartX &&
          endX === lastEndX &&
          scrollLeft === lastLeft &&
          scrollRight === lastRight &&
          duration === lastDuration
        ) {
          return
        }
        emitted = true
        lastStartX = startX
        lastEndX = endX
        lastLeft = scrollLeft
        lastRight = scrollRight
        lastDuration = duration
        this.wavesurferActions.setScrollPosition(scrollLeft)
        this.emit('scroll', startX * duration, endX * duration, scrollLeft, scrollRight)
      }, [percentages, bounds]),
    )
  }

  // Redraw
  this.scope.add(
    this.renderer.renderEpoch.subscribe(() => {
      this.emit('redraw')
    }),
  )

  // RedrawComplete
  this.scope.add(
    this.renderer.renderedEpoch.subscribe(() => {
      this.emit('redrawcomplete')
    }),
  )

  // Resize
  this.scope.add(
    this.renderer.resizeEpoch.subscribe(() => {
      this.emit('resize')
    }),
  )

  // Drag
  {
    let cancelDebounce: (() => void) | undefined
    const unsubscribeDrag = this.renderer.dragEventsSignal.subscribe((dragEvent) => {
      if (!dragEvent) return
      const { relativeX } = dragEvent

      if (dragEvent.type === 'start') {
        this.emit('dragstart', relativeX)
        return
      }

      if (dragEvent.type === 'end') {
        this.emit('dragend', relativeX)
        return
      }

      // 'move'
      if (!this.options.interact) return

      // Update the visual position
      this.renderer.renderProgress(relativeX)

      // Set the audio position with a debounce
      cancelDebounce?.()
      let debounceTime = 0

      const dragToSeek = this.options.dragToSeek
      if (this.isPlaying()) {
        debounceTime = 0
      } else if (dragToSeek === true) {
        debounceTime = 200
      } else if (dragToSeek && typeof dragToSeek === 'object') {
        debounceTime = (dragToSeek as { debounceTime: number }).debounceTime ?? 200
      }

      cancelDebounce = this.scope.timeout(() => {
        this.seekTo(relativeX)
      }, debounceTime)

      this.emit('interaction', relativeX * this.getDuration())
      this.emit('drag', relativeX)
    })

    // Unsubscribe the drag listener on destroy (the debounce timeout is
    // already torn down by this.scope itself via scope.timeout above).
    this.scope.add(unsubscribeDrag)
  }
}

private initPlugins() {
  if (!this.options.plugins?.length) return

  this.options.plugins.forEach((plugin) => {
    this.registerPlugin(plugin)
  })
}

private unsubscribePlayerEvents() {
  this.mediaEventScope.dispose()
  this.mediaEventScope = this.scope.child()
}

/** Set new wavesurfer options and re-render it */
public setOptions(options: Partial<WaveSurferOptions>) {
  if (this.isDestroyed) return
  this.options = Object.assign({}, this.options, options)
  if (options.duration && !options.peaks && this.decodedData) {
    // Rebuild the buffer from the existing decoded data with the new duration, keeping
    // every channel at its full resolution (exportPeaks() would downsample and drop channels).
    // Without decoded data there is nothing to rebuild: the option is just stored.
    const { numberOfChannels } = this.decodedData
 */
public loadBlob(blob: Blob, channelData?: WaveSurferOptions['peaks'], duration?: number): Promise<void> {
  return this.classifyLoadResult(this.loadAudio('', blob, channelData, duration))
}

/**
 * Swap in new pre-decoded peaks and duration and re-render, without a load:
 * no 'load'/'decode'/'ready' events, no load phase or load scope change,
 * and the media source and playback are left alone. For live previews that
 * redraw many times a second (the Record plugin's mic waveform).
 * Returns false and does nothing after destroy() or while a load() is in
 * flight, so a preview frame never interleaves with a real load.
 * Throws (changing nothing) on empty peaks or a non-positive duration.
 * @internal
 */
public replacePeaks(channelData: Array<Float32Array | number[]>, duration: number): boolean {
  if (this.isDestroyed || this.pendingLoadScope) return false
  const decodedData = Decoder.createBuffer(channelData, duration)
  this.decodedData = decodedData
  // A source-less WebAudioPlayer reports the duration it is given (see loadAudio)
  if (this.webAudioPlayer && !this.player.getSrc()) this.webAudioPlayer.duration = duration
  this.wavesurferActions.setPeaks(channelData)
  this.wavesurferActions.setAudioBuffer(decodedData)
  this.renderer.render(decodedData)
  return true
}

/** Zoom the waveform by a given pixels-per-second factor */
public zoom(minPxPerSec: number) {
  if (!this.decodedData) {
    throw new Error('No audio loaded')
  }
  this.renderer.zoom(minPxPerSec)
  this.wavesurferActions.setZoom(minPxPerSec)
  this.emit('zoom', minPxPerSec)
}

/** Get the decoded audio data */
public getDecodedData(): AudioBuffer | null {
  return this.decodedData
}

/** Get decoded peaks */
public exportPeaks({ channels = 2, maxLength = 8000, precision = 10_000 } = {}): Array<number[]> {
  if (!this.decodedData) {
    throw new Error('The audio has not been decoded yet')
  }
  const maxChannels = Math.min(channels, this.decodedData.numberOfChannels)
  const peaks = []
  for (let i = 0; i < maxChannels; i++) {
    const channel = this.decodedData.getChannelData(i)
    const data = []
    const sampleSize = channel.length / maxLength
    for (let j = 0; j < maxLength; j++) {
      const sample = channel.slice(Math.floor(j * sampleSize), Math.ceil((j + 1) * sampleSize))
      let max = 0
      for (let x = 0; x < sample.length; x++) {
        const n = sample[x]
        if (Math.abs(n) > Math.abs(max)) max = n
      }
      data.push(Math.round(max * precision) / precision)
    }
    peaks.push(data)
  }
  return peaks
}

/** Get the duration of the audio in seconds */
public getDuration(): number {
  let duration = this.player.getDuration() || 0
  // Fall back to the decoded data duration if the media duration is incorrect
  if ((duration === 0 || duration === Infinity) && this.decodedData) {
    duration = this.decodedData.duration
  }
  return duration
}

/** Toggle if the waveform should react to clicks */
public toggleInteraction(isInteractive: boolean) {
  this.options.interact = isInteractive
}

/** Jump to a specific time in the audio (in seconds) */
public setTime(time: number) {
  if (this.isDestroyed) return
  this.stopAtPosition = null
  this.player.setTime(time)
  this.updateProgress(time)
  this.emit('timeupdate', time)
}

/** Seek to a ratio of audio as [0..1] (0 = beginning, 1 = end) */
public seekTo(progress: number) {
  const time = this.getDuration() * progress
  this.setTime(time)
}

/** Pause the audio */
public pause(): void {
  if (this.isDestroyed) return
  this.player.pause()
}

/** Check if the audio is playing */
public isPlaying(): boolean {
  return this.player.isPlaying()
}

/** Check if the audio is seeking */
public isSeeking(): boolean {
  return this.player.isSeeking()
}

/** Get the current audio position in seconds */
public getCurrentTime(): number {
  return this.player.getCurrentTime()
}

/** Get the audio volume */
public getVolume(): number {
  return this.player.getVolume()
}

/** Set the audio volume */
public setVolume(volume: number) {
  if (this.isDestroyed) return
  this.player.setVolume(volume)
}

/** Get the audio muted state */
public getMuted(): boolean {
  return this.player.getMuted()
}

/** Mute or unmute the audio */
public setMuted(muted: boolean) {
  if (this.isDestroyed) return
  this.player.setMuted(muted)
}

/** Get the playback speed */
public getPlaybackRate(): number {
  return this.player.getPlaybackRate()
}

/** Set the playback speed, pass an optional false to NOT preserve the pitch */
public setPlaybackRate(rate: number, preservePitch?: boolean) {
  if (this.isDestroyed) return
  this.player.setPlaybackRate(rate, preservePitch)
}

/** Set a sink id to change the audio output device */
public setSinkId(sinkId: string): Promise<void> {
  if (this.isDestroyed) return Promise.resolve()
  return this.player.setSinkId(sinkId)
}

/**
 * Get the HTML media element.
 *
 * Returns `null` under the WebAudio backend (i.e. when the current media is
 * a WebAudioPlayer -- either `backend: 'WebAudio'` or a user-supplied
 * WebAudioPlayer), which has no HTML media element. Breaking change in v8:
 * previously the WebAudioPlayer itself was returned, mistyped as an
 * HTMLMediaElement.
 */
public getMediaElement(): HTMLMediaElement | null {
  // Invariant (see the webAudioPlayer field): non-null iff it IS the
  // player's current media.
  return this.webAudioPlayer ? null : this.player.getMediaElement()
}

/** Start playing the audio */
public async play(start?: number, end?: number): Promise<void> {
  // Terminal destroy: playing a destroyed instance would restart media
  // that Player.destroy() deliberately leaves untouched (user-supplied
  // elements). Resolve as a no-op, consistent with the other mutators.
  if (this.isDestroyed) return
  if (start != null) {
    this.setTime(start)
  }

  const playResult = await this.player.play()
  if (end != null) {
    if (this.webAudioPlayer) {
      this.webAudioPlayer.stopAt(end)
    } else {
      this.stopAtPosition = end
    }
  }

  return playResult
}

/** Play or pause the audio */
public async playPause(): Promise<void> {
  return this.isPlaying() ? this.pause() : this.play()
}

/** Stop the audio and go to the beginning */
public stop() {
  this.pause()
  this.setTime(0)
}

/** Skip N or -N seconds from the current position */
public skip(seconds: number) {
  this.setTime(this.getCurrentTime() + seconds)
}

/** Empty the waveform */
public empty() {
  // Fire-and-forget by design; failures surface via the 'error' event
  this.load('', [[0]], 0.001).catch(() => undefined)
}

/** Set HTML media element */
public setMediaElement(element: HTMLMediaElement) {
  if (this.isDestroyed) return
  this.unsubscribePlayerEvents()
  this.player.setMediaElement(element)
  // Re-classify: the new media may be (or replace) a WebAudioPlayer
  this.webAudioPlayer = element instanceof WebAudioPlayer ? element : null
  this.initPlayerEvents()
}

/**
 * Export the waveform image as a data-URI or a blob.
 *
 * @param format The format of the exported image, can be `image/png`, `image/jpeg`, `image/webp` or any other format supported by the browser.
 * @param quality The quality of the exported image, for `image/jpeg` or `image/webp`. Must be between 0 and 1.
 * @param type The type of the exported image, can be `dataURL` (default) or `blob`.
 * @returns A promise that resolves with an array of data-URLs or blobs, one for each canvas element.
 */
public async exportImage(format: string, quality: number, type: 'dataURL'): Promise<string[]>
public async exportImage(format: string, quality: number, type: 'blob'): Promise<Blob[]>
public async exportImage(
  format = 'image/png',
  quality = 1,
  type: 'dataURL' | 'blob' = 'dataURL',
): Promise<string[] | Blob[]> {

import { isHTMLElement } from './dom.js'
import * as utils from './renderer-utils.js'
import type { WaveSurferOptions } from './wavesurfer.js'
import { createDragStream, type DragEvent } from './reactive/drag-stream.js'
import { createScrollStream, type ScrollPercentages, type ScrollStream } from './reactive/scroll-stream.js'
import { computed, effect, signal, type ComputedSignal, type Signal } from './reactive/store.js'
import { Scope } from './scope.js'

type ChannelData = utils.ChannelData

/** A pointer hit on the waveform, in wrapper-relative [0..1] coordinates. */
export type RendererPointerHit = { relativeX: number; relativeY: number }

/** One step of a drag gesture on the waveform. */
export type RendererDragEvent = { type: 'start' | 'move' | 'end'; relativeX: number }

const SMOOTH_SCROLL_FPS = 60
const SMOOTH_SCROLL_MAX_DELTA = 10
const LOW_ZOOM_PIXELS_PER_SECOND_THRESHOLD = SMOOTH_SCROLL_MAX_DELTA * SMOOTH_SCROLL_FPS
const DRAG_EDGE_SIZE = 50
const DRAG_MAX_SCROLL_SPEED = 30

class Renderer {
  private options: WaveSurferOptions
  private parent: HTMLElement
  private container: HTMLElement
  private scrollContainer: HTMLElement
  private wrapper: HTMLElement
  private canvasWrapper: HTMLElement
  private progressWrapper: HTMLElement
  private cursor: HTMLElement
  // A signal (not a plain field) because visibleRange's auto-tracked computed
  // reads it: a scrollable transition (fit-to-width -> zoomed, or back) must
  // trigger a recompute even when nothing else changed that render -- e.g.
  // zoom() on the same audio leaves audioDuration untouched (Object.is
  // no-op), so a plain field here left visibleRange (and the lazy-render
  // effect subscribed to it) frozen with the dependency set collected on the
  // non-scrollable early-return branch.
  private isScrollable = signal(false)
  private audioData: AudioBuffer | null = null
  private lastContainerWidth = 0
  private isDragging = false
  private lastProgress: number | undefined
  private dragClientX: number | null = null
  private edgeScope: Scope | null = null
  private scope = new Scope()
  // Recreated (disposed + replaced) at the top of render()/reRender(), exactly
  // where `unsubscribeOnScroll.forEach(...); unsubscribeOnScroll = []` used to run.
  private scrollRenderScope = this.scope.child()
  // Recreated at the top of render() only, matching the original
  // `timeouts.forEach(clear); timeouts = []` there. Each pending delay()
  // registers its cancellation on the delayScope current at call time, so
  // both the next render() pass and destroy() can cancel it.
  private delayScope = this.scope.child()
  // Child of this.scope, created fresh in initDrag() and disposed+cleared in
  // disposeDrag(). Scoping the drag stream + its effect to their own child
  // (instead of registering their disposers straight onto this.scope) means
  // repeated setOptions({dragToSeek}) toggles dispose exactly what the last
  // initDrag() added -- a disposed child detaches itself from its parent, so
  // this.scope never accumulates stale disposers across toggles.
  private dragScope: Scope | null = null
  private dragStream: { signal: Signal<DragEvent | null>; cleanup: () => void } | null = null
  private scrollStream: ScrollStream | null = null
  private containerInlinePadding = 0
  private audioDuration = signal(0)
  private visibleRange: ComputedSignal<{ startTime: number; endTime: number }>

  // Reactive surface (writables stay private; the public accessors below
  // expose them read-only). This is Renderer's only outward communication
  // channel: WaveSurfer's initRendererEvents() is the single bridge that
  // translates these signals into public WaveSurferEvents. Pointer/drag
  // signals always set a FRESH object per event, so signal.set()'s Object.is
  // dedup can never swallow two identical consecutive gestures (e.g. two
  // clicks at the same spot).
  private _clickSignal = signal<RendererPointerHit | null>(null)
  private _dblclickSignal = signal<RendererPointerHit | null>(null)
  private _dragEventsSignal = signal<RendererDragEvent | null>(null)
  // Monotonic counters, incremented exactly where the old 'render' /
  // 'rendered' / 'resize' events were emitted (renderedEpoch keeps the
  // async Promise.resolve().then timing).
  private _renderEpoch = signal(0)
  private _renderedEpoch = signal(0)
  private _resizeEpoch = signal(0)
  // Captured from scrollStream at creation so getScrollSignals() stays valid
  // (the signals simply go quiet) even after destroy() nulls scrollStream.
  private scrollSignals!: { percentages: Signal<ScrollPercentages>; bounds: Signal<{ left: number; right: number }> }

  constructor(options: WaveSurferOptions, audioElement?: HTMLElement) {
    this.options = options

    const parent = this.parentFromOptionsContainer(options.container)
    this.parent = parent

    const [div, shadow] = this.initHtml()
    parent.appendChild(div)
    this.container = div
    this.scrollContainer = shadow.querySelector('.scroll') as HTMLElement
    this.wrapper = shadow.querySelector('.wrapper') as HTMLElement
    this.canvasWrapper = shadow.querySelector('.canvases') as HTMLElement
    this.progressWrapper = shadow.querySelector('.progress') as HTMLElement
    this.cursor = shadow.querySelector('.cursor') as HTMLElement
    this.calculateInlinePadding()

    if (audioElement) {
      shadow.appendChild(audioElement)
    }

    // initEvents() creates this.scrollStream, so visibleRange must be built
    // after it.
    this.initEvents()

    // Auto-tracked (no explicit dependency array): the early-return branch
    // reads only isScrollable + audioDuration, and a later transition to
    // scrollable re-collects the scrollStream.percentages dependency on the
    // recompute the isScrollable signal itself triggers. destroy() is
    // terminal (the instance is not reused), so the computed's disposal is
    // simply registered on this.scope.
    this.visibleRange = computed(() => {
      const duration = this.audioDuration.value
      if (!this.isScrollable.value || duration === 0 || !this.scrollStream) {
        return { startTime: 0, endTime: duration }
      }
      const { startX, endX } = this.scrollStream.percentages.value
      return { startTime: startX * duration, endTime: endX * duration }
    })
    this.scope.add(() => this.visibleRange.dispose())
  }

  private parentFromOptionsContainer(container: WaveSurferOptions['container']) {
    let parent
    if (typeof container === 'string') {
      parent = document.querySelector(container) satisfies HTMLElement | null
    } else if (isHTMLElement(container)) {
      parent = container
    }

    if (!parent) {
      throw new Error('Container not found')
    }

    return parent
  }

  private onClickWrapper = (e: MouseEvent) => {
    const rect = this.wrapper.getBoundingClientRect()
    const [x, y] = utils.getRelativePointerPosition(rect, e.clientX, e.clientY)
    this._clickSignal.set({ relativeX: x, relativeY: y })
  }

  private onDblClickWrapper = (e: MouseEvent) => {
    const rect = this.wrapper.getBoundingClientRect()
    const [x, y] = utils.getRelativePointerPosition(rect, e.clientX, e.clientY)
    this._dblclickSignal.set({ relativeX: x, relativeY: y })
  }

  private initEvents() {
    // Add a click listener
    this.scope.listen(this.wrapper, 'click', this.onClickWrapper as EventListener)

    // Add a double click listener
    this.scope.listen(this.wrapper, 'dblclick', this.onDblClickWrapper as EventListener)

    // Drag
    if (this.options.dragToSeek === true || typeof this.options.dragToSeek === 'object') {
      this.initDrag()
    }

    // Add a scroll listener using reactive stream. Consumers (the WaveSurfer
    // bridge) subscribe to the stream's signals directly via
    // getScrollSignals() -- no re-emit happens here.
    this.scrollStream = createScrollStream(this.scrollContainer)
    this.scrollSignals = { percentages: this.scrollStream.percentages, bounds: this.scrollStream.bounds }
    this.scope.add(() => {
      this.scrollStream?.cleanup()
      this.scrollStream = null
    })

    // Re-render the waveform on container resize
    if (typeof ResizeObserver === 'function') {
      const delay = this.createDelay(100)
      // The observer itself is scope-owned (createResizeObserver registers its
      // own disconnect on this.scope) -- no need to keep a field reference to
      // it here; nothing in this class ever read one.
      this.scope.createResizeObserver(this.scrollContainer, () => {
        delay()
          .then(() => this.onContainerResize())
          .catch(() => undefined)
      })
    }
  }

  private onContainerResize() {
    // A container resize changes the scrollContainer's clientWidth (and
    // potentially scrollWidth) without dispatching a 'scroll' event -- refresh
    // unconditionally, even when the early-return below skips a full
    // re-render, so visibleRange never reports stale metrics.
    this.scrollStream?.refresh()
    const width = this.parent.clientWidth
    this.calculateInlinePadding()
    if (width === this.lastContainerWidth && this.options.height !== 'auto') return
    this.lastContainerWidth = width
    this.reRender()
    this._resizeEpoch.update((n) => n + 1)
  }

  private initDrag() {
    // Don't initialize drag if it's already set up
    if (this.dragStream) return

    const dragScope = this.scope.child()
    this.dragScope = dragScope

    this.dragStream = createDragStream(this.wrapper)
    dragScope.add(() => {
      this.dragStream?.cleanup()
      this.dragStream = null
    })

    const unsubscribeDrag = effect(() => {
      const drag = this.dragStream!.signal.value
      const drag = this.dragStream!.signal.value
      if (!drag) return

      const rect = this.wrapper.getBoundingClientRect()
      const width = rect.width
      let relX = utils.clampToUnit(drag.x / width)

      if (drag.clientX !== undefined) {
        // The wrapper moves while auto-scrolling, so use the live pointer position
        relX = utils.clampToUnit((drag.clientX - rect.left) / width)
      }

      if (drag.type === 'start') {
        this.isDragging = true
        this.startEdgeScroll(dragScope)
        this._dragEventsSignal.set({ type: 'start', relativeX: relX })
      } else if (drag.type === 'move') {
        this._dragEventsSignal.set({ type: 'move', relativeX: relX })
      } else if (drag.type === 'end') {
        this.isDragging = false
        this.stopEdgeScroll()
        this._dragEventsSignal.set({ type: 'end', relativeX: relX })
      }

      if (this.isDragging && drag.clientX !== undefined) this.dragClientX = drag.clientX
    }, [this.dragStream.signal])

    dragScope.add(unsubscribeDrag)
  }

  /**
   * Tears down the drag stream + its effect by disposing their child scope
   * (see dragScope above), then clears the field so the next initDrag()
   * starts from a clean, freshly-created child of the current this.scope.
   * Safe to call when drag was never initialized (dragScope is null, or
   * already disposed from a prior destroy()) -- Scope#dispose() is a no-op
   * the second time.
   */
  private disposeDrag() {
    this.stopEdgeScroll()
    this.isDragging = false
    this.dragScope?.dispose()
    this.dragScope = null
  }

  private startEdgeScroll(parent: Scope) {
    this.stopEdgeScroll()
    const edgeScope = parent.child()
    this.edgeScope = edgeScope
    const tick = () => {
      const clientX = this.dragClientX
      if (clientX !== null && this.options.autoScroll) {
        const container = this.scrollContainer
        const box = container.getBoundingClientRect()
        const edge = Math.min(DRAG_EDGE_SIZE, box.width / 2)
        let speed = 0
        if (clientX < box.left + edge) {
          speed = -Math.min(1, (box.left + edge - clientX) / edge)
        } else if (clientX > box.right - edge) {
          speed = Math.min(1, (clientX - (box.right - edge)) / edge)
        }
        if (speed !== 0) {
          const before = container.scrollLeft
          container.scrollLeft += speed * DRAG_MAX_SCROLL_SPEED
          if (container.scrollLeft !== before) {
            const rect = this.wrapper.getBoundingClientRect()
            const relX = utils.clampToUnit((clientX - rect.left) / rect.width)
            this._dragEventsSignal.set({ type: 'move', relativeX: relX })
          }
        }
      }
      edgeScope.raf(tick)
    }
    edgeScope.raf(tick)
  }

  private stopEdgeScroll() {
    this.edgeScope?.dispose()
    this.edgeScope = null
    this.dragClientX = null
  }

  private calculateInlinePadding(): void {
    const { paddingLeft, paddingRight } = getComputedStyle(this.scrollContainer)
    const padding = parseFloat(paddingLeft) + parseFloat(paddingRight)
    this.containerInlinePadding = Number.isNaN(padding) ? 0 : padding
  }

  private initHtml(): [HTMLElement, ShadowRoot] {
    const div = document.createElement('div')
    const shadow = div.attachShadow({ mode: 'open' })

    const cspNonce =
      this.options.cspNonce && typeof this.options.cspNonce === 'string' ? this.options.cspNonce.replace(/"/g, '') : ''

    shadow.innerHTML = `
      <style${cspNonce ? ` nonce="${cspNonce}"` : ''}>
        :host {
          user-select: none;
          min-width: 1px;
        }
        :host audio {
          display: block;
          width: 100%;
        }
        :host .scroll {
          overflow-x: auto;
          overflow-y: hidden;
          width: 100%;
          position: relative;
        }
        :host .noScrollbar {
          scrollbar-color: transparent;
          scrollbar-width: none;
        }
        :host .noScrollbar::-webkit-scrollbar {
          display: none;
          -webkit-appearance: none;
        }
        :host .wrapper {
          position: relative;
          overflow: visible;
          z-index: 2;
        }
        :host .canvases {
          pointer-events: none;
        }
        :host .canvases > div {
          position: relative;
        }
        :host canvas {
          display: block;
          position: absolute;
          top: 0;
          image-rendering: pixelated;
        }
        :host .progress {
          pointer-events: none;
          position: absolute;
          z-index: 2;
          top: 0;
          left: 0;
          width: 0;
          height: 100%;
          overflow: hidden;
        }
        :host .progress > div {
          position: relative;
        }
        :host .cursor {
          pointer-events: none;
          position: absolute;
          z-index: 5;
